// Prior evidence: the ship twice entered Origin's 185-unit activation
// envelope and then reclaimed the departure pad. ONE replay of that exact
// reset is enough; we stop rather than burn another blind long flight.
const d = s.systemFlight?.originCentreDistance ?? null;
if (d !== null) {
  if (d <= 185 && !enteredEnvelope) {
    enteredEnvelope = true; deepest = d;
    mark('origin-envelope-entered', s, `d=${d} (<=185 activation envelope) active=${s.systemFlight?.activePlanetId} epoch=${s.systemFlight?.activationEpoch}`);
  }
  if (enteredEnvelope && d < deepest) deepest = d;
  if (enteredEnvelope && d > 1000) {
    mark('departure-reset', s, `d=${d} after deepest=${deepest}; active=${s.systemFlight?.activePlanetId} last=${s.systemFlight?.lastActivePlanetId} epoch=${s.systemFlight?.activationEpoch}`);
    report.knownBlockerReplayed = { deepestCentreDistance: deepest, resetCentreDistance: d, atMs: s.atMs, sample: s };
    await shot(`${String(report.samples).padStart(4, '0')}-departure-reset.png`, `reset to d=${d} after deepest=${deepest}`);
    break;
  }
}
prev = s;
if (s.originLandedMilestone) { mark('origin-landed', s, 'story:ch13-origin-landed latched'); break; }

